def refs():
    return [{**s, "subject": "science", "locator": "控制變因、對照組、透水鋪面、雨水循環、逕流、入滲、生態與校園環境資料判讀", "observedPattern": "公開學校自然與環境教育資料常以實驗組／對照組、校園水循環與透水設施情境，要求辨識變因、證據與環境效益；本題只採能力方向與資料型態。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for s in SOURCES]


def make(n, prompt, options, explanation, strategy, steps, difficulty):
    return {"id": f"question-science-content-cross-disciplinary-{n}", "subject": "science", "type": "single-choice", "prompt": prompt, "options": [{"id": k, "text": v} for k, v in options.items()], "knowledgeIds": [KG], "difficulty": difficulty, "answer": {"value": "A", "explanation": explanation + "選 A。"}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0]["url"], "sourceLocator": "三筆公立學校公開自然／環境教育資料僅供控制變因、透水鋪面、雨水循環與系統決策的能力方向研究；本題未複製原題、選項、圖表或答案。", "authoringNote": "依官方課綱、KG 與三筆公立學校公開資料的能力方向獨立改寫；題幹、選項、答案、解析與五步解法均為原創，待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-10", "lessonId": LESSON, "examPatternRefs": refs(), "solutionStrategy": strategy, "solutionSteps": steps}


Q = [
    make(1, "比較水泥地與透水鋪面對降雨後逕流量的影響時，最先應控制哪些條件？", {"A": "降雨量、坡度、面積與測量時間盡量相同，只改變鋪面", "B": "同時改變鋪面、坡度、土壤厚度與降雨量", "C": "只挑選結果最漂亮的那一次觀察", "D": "不記錄測量時間，直接比較最後照片"}, "一次只改變主要自變因，並固定其他會影響逕流的條件，才能把差異合理歸因於鋪面。", "先列出研究自變因，再逐一找出必須固定的干擾變因。", ["把鋪面種類列為要比較的自變因。", "列出降雨、坡度、面積與時間等可能影響量。", "將這些條件在兩組盡量固定。", "只比較相同條件下的逕流量差異。", "所以選 A。"], "easy"),
    make(2, "某校園改造後積水時間縮短，但同時改了排水孔和土壤厚度。此結果最大的解釋限制是？", {"A": "無法單獨判定縮短效果來自哪一個改動，需要分組或逐項控制", "B": "只要積水變少，就能證明排水孔是唯一原因", "C": "土壤厚度與水流完全無關", "D": "改造後所有環境效益都已被證明"}, "同時改變多個因素會產生混淆變因，觀察到的總效果不能直接分配給其中一項。", "檢查研究設計是否能把因果來源拆開，而不是只看結果方向。", ["列出這次同時改變的兩個以上因素。", "確認積水時間是多因素共同影響的結果。", "判斷目前設計不能隔離單一因素的效果。", "提出分組或一次只改一項的後續設計。", "所以選 A。"], "medium"),
    make(3, "透水鋪面常被期待能減少地表逕流，哪一條因果鏈最合理？", {"A": "雨水較能下滲土壤，地表暫時聚集的水量可能下降，但效果受土壤與降雨強度限制", "B": "透水鋪面會把所有雨水蒸發，因此不必考慮排水", "C": "只要鋪面有孔洞，任何暴雨都不會形成逕流", "D": "透水鋪面一定會讓地下水立刻增加相同體積"}, "透水設施可增加入滲機會，但土壤飽和、降雨強度與排水設計都會改變效果，不能誇大成無條件定律。", "把設施功能、系統條件與適用限制放在同一條因果鏈檢查。", ["從降雨到地表水流列出可能路徑。", "指出透水層增加水進入土壤的機會。", "檢查土壤是否已飽和及雨勢是否超過入滲能力。", "保留逕流仍可能發生的條件限制。", "所以選 A。"], "medium"),
    make(4, "植被區比水泥地低 3°C，若要判斷是否真由植被造成，下一步最適合做什麼？", {"A": "在相同時段與相同測點重複測量，記錄日照、風速與地表材料作對照", "B": "只保留溫差最大的單次讀值", "C": "直接宣布植物是唯一降溫原因", "D": "刪除所有不符合預期的資料"}, "溫差是觀察，不是單一因果證明；重複、對照與記錄環境條件能提升可比性。", "從一次結果回到可重複、可比較的測量設計。", ["把 3°C 列為一次觀察結果。", "找出可能同時影響溫度的日照與風等條件。", "設計相同時段和測點的對照測量。", "重複記錄並保留變異與誤差。", "所以選 A。"], "medium"),
    make(5, "評估雨水花園方案時，哪一組資料最能避免『單一指標最好就代表整體最佳』？", {"A": "同時比較逕流量、入滲時間、地表溫度、植物存活、維護成本與安全性", "B": "只比較改造後照片的綠色面積", "C": "只選成本最低的方案，不看水與生物資料", "D": "只看一次暴雨的積水深度"}, "跨科方案同時涉及水、熱、生物、工程與資源；多項指標和適用條件才能支撐較完整的決策。", "先確認決策問題的多個目標，再建立指標矩陣而不是只選一項。", ["列出方案要處理的水文目標。", "補上熱環境、生物、成本與安全的指標。", "比較各方案在相同條件下的資料。", "說明指標間可能互相取捨，不能只看單一最高分。", "所以選 A。"], "hard"),
    make(6, "在雨水花園系統圖中，『降雨增加→逕流增加→低窪區積水』屬於哪一種內容？", {"A": "根據系統中可觀察或可測量變項提出的因果模型，仍需資料檢驗", "B": "不需測量就已經證明的價值判斷", "C": "與土壤、坡度和鋪面無關的固定定律", "D": "只描述方案成本的行政決策"}, "箭頭表達變項間的假設關係，需由測量資料與控制條件檢驗，不等同於直接觀察或價值選擇。", "把系統圖中的觀察、模型假設和決策價值分欄。", ["確認降雨、逕流與積水都是可定義的變項。", "判斷箭頭是對關係的模型化表達。", "提出需要測量和對照來檢驗的方式。", "排除把模型直接當成已證明定律。", "所以選 A。"], "medium"),
    make(7, "同一場雨中，透水鋪面區的入滲時間比水泥地長或短，應如何解釋才較嚴謹？", {"A": "先確認入滲時間的定義、測點與土壤條件，再用重複資料判斷差異是否穩定", "B": "只要一次讀值不同，就能推廣到所有場地", "C": "入滲時間只由鋪面決定，土壤狀態不重要", "D": "時間越長就一定表示方案越差"}, "入滲受鋪面、土壤含水量、降雨強度與測點影響；先定義測量和重複檢查，才能避免過度解讀。", "先處理測量定義與條件，再比較趨勢和方案目的。", ["明確寫出從何時到何時算入滲時間。", "確認兩區測點、土壤與雨勢是否可比。", "重複測量並觀察差異是否一致。", "再問較長或較短是否符合該方案的整體目標。", "所以選 A。"], "hard"),
    make(8, "若植栽在第一次暴雨後存活，但三週後大多枯萎，方案評估應如何更新？", {"A": "把短期耐淹與長期存活分開評估，增加土壤含水、日照、維護與季節資料", "B": "只保留第一次存活結果，因為後續資料會干擾結論", "C": "直接判定雨水花園一定失敗，不必查原因", "D": "把枯萎全部歸因於植物種類而不看環境"}, "短期一次觀察不能代表長期適應；需要延長觀測並加入環境與維護變項。", "區分時間尺度，讓評估從單次結果更新成可追蹤的證據。", ["分開記錄暴雨後短期反應與三週後狀態。", "列出日照、含水量、季節和維護等可能因素。", "規劃持續測量與植物存活率資料。", "用新資料修正原本的模型與方案判斷。", "所以選 A。"], "medium"),
    make(9, "社區要求方案兼顧防洪、降溫與維護預算。哪一種結論最符合科學與公共決策的分工？", {"A": "先用資料說明各方案在不同指標的效果，再把預算與使用者偏好明確列為決策條件", "B": "只要科學資料最好，就能忽略預算與居民需求", "C": "居民偏好可以直接改寫測量結果", "D": "預算最低的方案必定具有最高生態效益"}, "科學資料用來描述效果與不確定性，預算和偏好是價值與可行性條件；兩者都重要但不能互相冒充。", "把經驗資料、模型推論和價值選擇分開呈現，再做透明取捨。", ["列出每個方案可測量的效果指標。", "標示資料的誤差和適用條件。", "另外列出成本、維護與使用者需求。", "說明最後選擇是依哪些條件取捨，而非假稱為單一科學答案。", "所以選 A。"], "hard"),
    make(10, "跨科探究報告的結論段落，哪種寫法最完整？", {"A": "交代測量證據、模型推論、未控制變因、適用條件與下一步查證方法", "B": "只寫『方案有效』，不附資料或條件", "C": "把模擬畫面當成真實長期結果", "D": "只列出支持方案的資料，刪除反例"}, "跨科結論必須讓讀者看見證據到推論的路徑，也要交代限制和下一步，才能避免把一次結果誇張成普遍定律。", "使用證據—推論—限制—後續行動四欄檢查結論。", ["列出真正量到的數據與測量條件。", "說明數據支持的模型推論。", "寫出未控制變因和不能外推的範圍。", "提出下一步重複或補充測量。", "所以選 A。"], "medium"),
]

for index, target in {2: "B", 4: "C", 6: "D", 8: "B", 10: "C"}.items():
    q = Q[index - 1]
    option_map = {o["id"]: o["text"] for o in q["options"]}
    option_map["A"], option_map[target] = option_map[target], option_map["A"]
    q["options"] = [{"id": k, "text": option_map[k]} for k in ("A", "B", "C", "D")]
    q["answer"]["value"] = target
    q["answer"]["explanation"] = q["answer"]["explanation"].replace("選 A。", f"選 {target}。")
    q["solutionSteps"] = [s.replace("所以選 A。", f"所以選 {target}。") for s in q["solutionSteps"]]

for q in Q:
    (OUT / f"{q['id']}.json").write_text(json.dumps(q, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(f"rewrote {len(Q)} questions")
